package net.officefloor.hq.app.role;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** The user's role on the sheet may not take the action, by the sheet's permission matrix. */
@ResponseStatus(HttpStatus.FORBIDDEN)
public class ActionNotAllowedException extends RuntimeException {

    public ActionNotAllowedException(String action) {
        super("Your role may not " + action + " here.");
    }
}
package net.officefloor.hq.app.role;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** Another user set the same name's first role at the same moment. */
@ResponseStatus(HttpStatus.CONFLICT)
public class RoleConflictException extends RuntimeException {

    public RoleConflictException() {
        super("The role was changed at the same moment; try again.");
    }
}
package net.officefloor.hq.app.role;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The roles the sheet gives user names. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/roles")
public class RoleController {

    public record RoleView(String user, String role) {

        static RoleView of(SheetRole role) {
            return new RoleView(role.getUserName(), role.getRole());
        }
    }

    public record RoleRequest(@NotBlank @Size(max = 200) String user,
            @NotBlank @Pattern(regexp = "clerk|steward") String role) {
    }

    private final RoleService service;

    public RoleController(RoleService service) {
        this.service = service;
    }

    /** The names given a role on the sheet, by name; any other name is a clerk. */
    @GetMapping
    public List<RoleView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user) {
        return service.list(sheetId.trim()).stream().map(RoleView::of).toList();
    }

    /** Give a user name a role: clerk or steward. */
    @PutMapping
    public RoleView set(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid RoleRequest request) {
        return RoleView.of(service.set(sheetId.trim(), user.trim(), request.user().trim(), request.role()));
    }
}
package net.officefloor.hq.app.role;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps the role each sheet gives a user name: clerk (any name with none) or steward. */
@Service
public class RoleService {

    private final SheetRoleRepository roles;
    private final SheetRepository sheets;
    private final Audit audit;

    public RoleService(SheetRoleRepository roles, SheetRepository sheets, Audit audit) {
        this.roles = roles;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<SheetRole> list(String sheetId) {
        requireSheet(sheetId);
        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
    }

    /** Give a user name a role on the sheet, replacing the one it had. */
    @Transactional
    public SheetRole set(String sheetId, String user, String name, String role) {
        requireSheet(sheetId);
        SheetRole row = roles.findBySheetIdAndUserName(sheetId, name).orElse(null);
        if (row == null) {
            try {
                row = roles.saveAndFlush(new SheetRole(sheetId, name, role));
            } catch (DataIntegrityViolationException e) {
                throw new RoleConflictException();
            }
        } else {
            row.setRole(role);
            row = roles.saveAndFlush(row);
        }
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role);
        return row;
    }

    /** Whether the sheet makes the user name a steward. */
    @Transactional(readOnly = true)
    public boolean isSteward(String sheetId, String name) {
        return roles.findBySheetIdAndUserName(sheetId, name)
                .map(r -> SheetRole.STEWARD.equals(r.getRole()))
                .orElse(false);
    }

    /** Whether the user's role on the sheet may take an action, by the sheet's permission matrix (an action
     *  with no roles set keeps the standing rule). */
    @Transactional(readOnly = true)
    public boolean allows(String sheetId, String name, String action) {
        String role = isSteward(sheetId, name) ? SheetRole.STEWARD : SheetRole.CLERK;
        return sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new).allows(action, role);
    }

    /** Refuse an action the user's role on the sheet may not take. */
    public void require(String sheetId, String name, String action) {
        if (!allows(sheetId, name, action)) {
            throw new ActionNotAllowedException(action);
        }
    }

    private void requireSheet(String sheetId) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException();
        }
    }
}
